import sys
from datetime import date, timedelta, datetime


def minutes(text):
    h, m = text.split(":")
    return int(h) * 60 + int(m)


def clock(total):
    return f"{total // 60:02d}:{total % 60:02d}"


def main():
    settings = {}
    busy = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if not parts:
            continue
        if parts[0] == "busy":
            who, day_str, start_str, end_str = parts[1], parts[2], parts[3], parts[4]
            day = date.fromisoformat(day_str)
            start = minutes(start_str)
            end = minutes(end_str)
            busy.setdefault((who, day.isoformat()), []).append((start, end))
        else:
            settings[parts[0]] = parts[1:]

    first = date.fromisoformat(settings["days"][0])
    last = date.fromisoformat(settings["days"][1])
    open_at, close_at = (minutes(t) for t in settings["hours"])
    need = int(settings["duration"][0])
    buffer = int(settings.get("buffer", [0])[0]) if settings.get("buffer") else 0

    day = first
    while day <= last:
        day_str = day.isoformat()
        taken = sorted(busy.get(("A", day_str), []) + busy.get(("B", day_str), []))
        if day.weekday() >= 5:  # skip weekends
            day += timedelta(days=1)
            continue

        free_slots = []
        cursor = open_at
        for start, end in taken:
            if cursor < start:
                if end - cursor >= need:
                    free_slots.append((clock(cursor), clock(start)))
            cursor = end

        if close_at - cursor >= need:
            free_slots.append((clock(cursor), clock(close_at)))

        # Apply buffer to each free slot
        buffered_slots = []
        for start_t, end_t in free_slots:
            start_t -= buffer
            end_t += buffer
            buffered_slots.append((start_t, end_t))

        # Filter slots that are at least 'need' minutes long
        valid_slots = []
        for i in range(len(buffered_slots) - 1):
            s1, e1 = buffered_slots[i]
            s2, e2 = buffered_slots[i + 1]
            if e1 - s1 >= need:
                valid_slots.append((s1, e1))

        formatted = [f"{slot[0]:05d}-{slot[1]:05d}" for slot in valid_slots]
        print(f"{day_str} {' '.join(formatted) if formatted else 'none'}")
        day += timedelta(days=1)


if __name__ == "__main__":
    main()
